```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, M, C;
    if (scanf("%d %d %d", &N, &M, &C) != 3) return 0;

    int *next = (int *)calloc(M + 1, sizeof(int));
    if (!next) return 0;

    for (int i = 0; i < N; i++) {
        int A, D;
        scanf("%d %d", &A, &D);
        if (next[D] == 0) {
            next[D] = A;
        }
    }

    int *visited = (int *)malloc((M + 1) * sizeof(int));
    if (!visited) {
        free(next);
        return 0;
    }

    for (int i = 0; i <= M; i++) {
        visited[i] = -1;
    }

    int cur = C;
    int swaps = 0;

    while (next[cur] != 0) {
        if (visited[cur] != -1) {
            printf("-1\n");
            free(next);
            free(visited);
            return 0;
        }

        visited[cur] = swaps;
        cur = next[cur];
        swaps++;
    }

    printf("%d\n", swaps);

    free(next);
    free(visited);
    return 0;
}
```

